import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Stream from 'flarum/common/utils/Stream';
import { call, failure, noSubmit } from '../api';
const t = key => app.translator.trans('smstunnel-sms.admin.' + key);

/**
 * The API key is write-only here: the server answers whether one is saved, never the key.
 */
export default class KeySetting extends Component {
  loading = true;
  busy = false;
  hasKey = false;
  input = Stream('');
  message = null;
  isError = false;
  oninit(vnode) {
    super.oninit(vnode);
    call('GET', '').then(state => this.hasKey = state.hasKey).catch(error => this.show(failure(error), true)).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
  view() {
    if (this.loading) return m(LoadingIndicator, {
      display: "inline"
    });
    return m("div", {
      className: "SmstunnelAdmin"
    }, m("p", null, t('intro')), m("h3", null, t('key.heading')), m("p", {
      className: "helpText"
    }, this.hasKey ? t('key.saved') : t('key.none')), m("div", {
      className: "SmstunnelAdmin-row"
    }, m("input", {
      className: "FormControl",
      type: "password",
      autocomplete: "off",
      "aria-label": t('key.label'),
      placeholder: t('key.placeholder'),
      bidi: this.input,
      onkeydown: noSubmit
    }), m(Button, {
      className: "Button Button--primary",
      type: "button",
      loading: this.busy,
      onclick: () => this.save()
    }, t('key.save')), this.hasKey ? m(Button, {
      className: "Button",
      type: "button",
      loading: this.busy,
      onclick: () => this.remove()
    }, t('key.remove')) : null), m("p", {
      className: "helpText"
    }, t('get_key')), this.message ? m("p", {
      className: 'SmstunnelAdmin-message' + (this.isError ? ' SmstunnelAdmin-message--error' : ''),
      role: "status"
    }, this.message) : null);
  }
  save() {
    this.run(call('POST', '/key', {
      key: this.input().trim()
    }), () => {
      this.hasKey = true;
      this.input('');
      this.show(t('key.stored'), false);
    });
  }
  remove() {
    this.run(call('DELETE', '/key'), () => {
      this.hasKey = false;
      this.show(t('key.removed'), false);
    });
  }
  run(request, done) {
    this.busy = true;
    this.message = null;
    request.then(done).catch(error => this.show(failure(error), true)).finally(() => {
      this.busy = false;
      m.redraw();
    });
  }
  show(message, isError) {
    this.message = message;
    this.isError = isError;
  }
}
flarum.reg.add('smstunnel-sms', 'admin/components/KeySetting', KeySetting);